def transform(grid):
    # Fill the interiors of outlined rectangular frames. Odd-area interiors
    # receive 7; even-area interiors receive 2.
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)
    for color in set(counts) - {bg}:
        for r0 in range(h):
            for r1 in range(r0 + 2, h):
                for c0 in range(w):
                    for c1 in range(c0 + 2, w):
                        if (all(grid[r0][c] == color and grid[r1][c] == color
                                for c in range(c0, c1 + 1)) and
                            all(grid[r][c0] == color and grid[r][c1] == color
                                for r in range(r0, r1 + 1))):
                            inside = [grid[r][c] for r in range(r0 + 1, r1)
                                      for c in range(c0 + 1, c1)]
                            if inside and all(value == bg for value in inside):
                                fill = 7 if len(inside) % 2 else 2
                                for r in range(r0 + 1, r1):
                                    for c in range(c0 + 1, c1):
                                        out[r][c] = fill
    return out
